 {tool==='Qualification'&&<>{[['problem','Business problem and impact'],['profile','Site, workforce / users, shifts and current tools'],['authority','Decision-maker, approver and buying process'],['budget','Budget status and commercial expectations'],['timeline','Timeline, constraints and dependencies'],['success','Measurable success / solution fit'],['next','Agreed next action, owner and date']].map(([key,label])=><Field key={key} label={label}><textarea name={key} required rows={2}/></Field>)}</>}
